const input = $input.item.json || {};

const parseInteger = (value, fallback) => {
  const parsed = parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const firstString = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
};

const normalizeUrl = (value) => {
  const original = String(value ?? '').trim();
  if (!original) {
    throw new Error('Missing required input field url');
  }

  let url = original
    .replace(/[\u0000-\u001F\u007F]/g, '')
    .trim();

  // Accept angle-bracketed URLs copied from chat/Slack/Markdown.
  const angleMatch = url.match(/^<(.+)>$/);
  if (angleMatch) {
    url = angleMatch[1].trim();
  }

  // Accept an already-built Jina Reader URL, but normalize it back to the target URL.
  url = url.replace(/^https?:\/\/r\.jina\.ai\//i, '').trim();

  // Match the working Brave workflow pattern: keep the target URL as a string and
  // build the Reader URL as https://r.jina.ai/${url}. Avoid new URL(...), which is
  // unnecessary here and previously failed inside n8n Code-node handling.
  if (url.startsWith('//')) {
    url = `https:${url}`;
  }

  // Fix accidental single-slash protocol forms like https:/example.com/page.
  url = url.replace(/^(https?:)\/(?!\/)/i, '$1//');

  // Treat bare hostnames as HTTPS URLs.
  if (!/^https?:\/\//i.test(url)) {
    if (!/^[a-z0-9.-]+\.[a-z]{2,}([/:?#]|$)/i.test(url)) {
      throw new Error('Invalid URL input - expected HTTP URL, HTTPS URL, protocol-relative URL, or bare hostname');
    }
    url = `https://${url}`;
  }

  if (!/^https?:\/\/[^\s]+/i.test(url)) {
    throw new Error('Invalid URL input - expected HTTP or HTTPS URL');
  }

  const hostname = url.replace(/^https?:\/\//i, '').split(/[/?#]/)[0];
  if (!hostname || hostname.includes(' ') || !hostname.includes('.')) {
    throw new Error('Invalid URL input - hostname is missing or malformed');
  }

  return url;
};

const url = normalizeUrl(firstString(input.url, input.targetUrl, input.sourceUrl, input.href, input.link));
const maxContentChars = clamp(parseInteger(input.maxContentChars ?? input.max_content_chars, 6000), 1000, 200000);
const requestTimeoutMs = clamp(parseInteger(input.requestTimeoutMs ?? input.request_timeout_ms, 60000), 1000, 300000);

const rateLimitMaxRequests = clamp(parseInteger(input.rateLimitMaxRequests ?? input.rate_limit_max_requests, 20), 1, 1000);
const rateLimitWindowSeconds = clamp(parseInteger(input.rateLimitWindowSeconds ?? input.rate_limit_window_seconds, 60), 1, 3600);
const rateLimitSleepBufferSeconds = clamp(parseInteger(input.rateLimitSleepBufferSeconds ?? input.rate_limit_sleep_buffer_seconds, 5), 0, 3600);
const redisRateLimitKey = firstString(
  input.redisRateLimitKey,
  input.redis_rate_limit_key,
  input.rateLimitKey,
  input.rate_limit_key,
) || 'jina_reader:free:rpm';

return {
  json: {
    url,
    readerUrl: `https://r.jina.ai/${url}`,
    maxContentChars,
    requestTimeoutMs,
    provider: 'jina_reader',
    requestedAt: new Date().toISOString(),
    request: {
      url,
      maxContentChars,
      requestTimeoutMs,
      redisRateLimitKey,
      rateLimitMaxRequests,
      rateLimitWindowSeconds,
      rateLimitSleepBufferSeconds
    },
    rateLimit: {
      enabled: true,
      provider: 'redis',
      redisKey: redisRateLimitKey,
      limit: rateLimitMaxRequests,
      windowSeconds: rateLimitWindowSeconds,
      sleepBufferSeconds: rateLimitSleepBufferSeconds,
      strategy: 'simple_counter_increment_before_request_reset_ttl_60s'
    }
  }
};

const request = $('Normalize Input').first().json;
const redisOutput = $input.item.json || {};
const redisKey = request.rateLimit.redisKey;

const rawCounter = redisOutput[redisKey] ?? Object.values(redisOutput)[0] ?? 0;
const counter = Number.parseInt(rawCounter, 10);
const safeCounter = Number.isFinite(counter) ? counter : 0;

const limit = request.rateLimit.limit;
const remainingTtlSeconds = request.rateLimit.windowSeconds;
const waitSeconds = remainingTtlSeconds + request.rateLimit.sleepBufferSeconds;
const allowed = safeCounter <= limit;

return {
  json: {
    ...request,
    rateLimit: {
      ...request.rateLimit,
      counter: safeCounter,
      allowed,
      hit: !allowed,
      remainingTtlSeconds,
      waitSeconds,
      checkedAt: new Date().toISOString(),
      note: allowed
        ? 'Counter is within the configured free Jina Reader limit.'
        : 'Counter exceeded the configured limit. Wait remaining TTL plus buffer, then increment and check again.'
    }
  }
};

const source = $('Attach Rate Limit State').first().json;
const response = $input.item.json;

let content = '';
if (typeof response === 'string') {
  content = response;
} else if (typeof response?.data === 'string') {
  content = response.data;
} else if (typeof response?.body === 'string') {
  content = response.body;
} else {
  content = JSON.stringify(response ?? {});
}

const maxContentChars = source.maxContentChars || 6000;
const originalContentChars = content.length;
const truncatedContent = content.slice(0, maxContentChars);

return {
  json: {
    status: 'ok',
    provider: 'jina_reader',
    url: source.url,
    readerUrl: source.readerUrl,
    fetched: true,
    contentType: 'markdown',
    contentChars: truncatedContent.length,
    originalContentChars,
    truncated: originalContentChars > maxContentChars,
    // Preferred key for downstream workflows and AI nodes.
    content: truncatedContent,
    reader: {
      status: 'ok',
      fetched: true,
      provider: 'jina_reader',
      readerUrl: source.readerUrl
    },
    rateLimit: source.rateLimit,
    request: source.request,
    metadata: {
      strategy: 'single_url_jina_reader_free_endpoint_with_redis_simple_counter_rate_limit',
      contentKey: 'content',
      contentKeyNote: 'Use top-level content as the preferred key for the markdown read from the URL.',
      maxContentChars,
      requestTimeoutMs: source.requestTimeoutMs,
      rateLimitStrategy: source.rateLimit.strategy
    },
    receivedAt: new Date().toISOString()
  }
};

let source = {};
let rateLimitSource = {};
let originalInput = {};

try {
  source = $('Normalize Input').first().json || {};
} catch (error) {
  source = {};
}

try {
  rateLimitSource = $('Attach Rate Limit State').first().json || {};
} catch (error) {
  rateLimitSource = {};
}

try {
  originalInput = $('When Executed by Another Workflow').first().json || {};
} catch (error) {
  originalInput = {};
}

const input = $input.item.json || {};
const rawError = input.error ?? input;

const errorMessage = (() => {
  if (typeof rawError === 'string' && rawError.trim()) return rawError.trim();
  if (rawError && typeof rawError.message === 'string' && rawError.message.trim()) return rawError.message.trim();
  if (typeof input.message === 'string' && input.message.trim()) return input.message.trim();
  return 'Jina Reader workflow failed';
})();

const errorName = (() => {
  if (rawError && typeof rawError === 'object' && rawError.name) return rawError.name;
  if (input.name) return input.name;
  return null;
})();

const statusCode = (() => {
  if (rawError && typeof rawError === 'object') {
    return rawError.statusCode || rawError.status || rawError.httpCode || null;
  }
  return input.statusCode || input.status || null;
})();

const bestSource = Object.keys(rateLimitSource).length ? rateLimitSource : source;
const attemptedUrl = bestSource.url || originalInput.url || originalInput.targetUrl || originalInput.sourceUrl || originalInput.href || originalInput.link || null;
const attemptedReaderUrl = bestSource.readerUrl || null;
const inputPreview = JSON.stringify({ originalInput, errorInput: input }).slice(0, 1000);

return {
  json: {
    status: 'error',
    provider: 'jina_reader',
    url: attemptedUrl,
    readerUrl: attemptedReaderUrl,
    fetched: false,
    content: null,
    contentChars: 0,
    originalContentChars: 0,
    truncated: false,
    error: {
      message: errorMessage,
      name: errorName,
      statusCode
    },
    rateLimit: bestSource.rateLimit || source.rateLimit || null,
    request: bestSource.request || source.request || {
      input: originalInput
    },
    metadata: {
      strategy: 'single_url_jina_reader_free_endpoint_with_redis_simple_counter_rate_limit',
      contentKey: 'content',
      urlHandling: 'string_only_brave_workflow_style',
      inputPreview
    },
    receivedAt: new Date().toISOString()
  }
};
